\title{Solver Trace Ablation Reveals Reward Hacking and Meta-Level Goodhart's Law in a GRPO-Trained Neurosymbolic Formalizer: A Case Study with Qwen3-4B}

\author{Anonymous ACL submission}

\begin{document}
\maketitle

\input{abstract}
\input{introduction}
\input{related_work}
